const { incomeJson, grossAnnual, applicationDate } = input.config();

// Take the first non-empty value (handles lookup arrays)
function firstVal(v) {
  if (Array.isArray(v)) return v.find(x => x !== null && x !== undefined && String(x).trim() !== "") ?? null;
  return v ?? null;
}

// Handles either:
// 1) '{...}' (normal JSON text)
// 2) '"{...}"' (JSON wrapped in quotes) with escaped quotes inside
function parsePossiblyQuotedJson(v) {
  const s0 = String(v ?? "").trim();
  if (!s0) return null;

  // Try normal parse first
  try { return JSON.parse(s0); } catch (_) {}

  // If it's wrapped in quotes, unquote + unescape and try again
  if (
    (s0.startsWith('"') && s0.endsWith('"')) ||
    (s0.startsWith("'") && s0.endsWith("'"))
  ) {
    const inner = s0.slice(1, -1).replace(/\\"/g, '"');
    return JSON.parse(inner);
  }

  // Last resort: throw original parse error
  return JSON.parse(s0);
}

function toNumber(x) {
  return Number(String(x).replace(/[,$\s]/g, ""));
}
function normalizeUnix(ts) {
  const n = toNumber(ts);
  return n < 1e12 ? n * 1000 : n; // seconds -> ms
}

const incomeStr = firstVal(incomeJson);                 // <-- unwrap lookup array
const appDateRaw = firstVal(applicationDate);           // <-- unwrap lookup array
const gross = toNumber(firstVal(grossAnnual));
const appMs = normalizeUnix(appDateRaw);

const data = parsePossiblyQuotedJson(incomeStr);
if (!data) throw new Error("incomeJson was empty/unparseable.");

// since you link by size already, take the first top-level key ("4")
const sizeKey = Object.keys(data)[0];
const sizeBlock = data[sizeKey];

function pickEffective(calcName) {
  const block = sizeBlock?.[calcName];
  if (!block) return null;

  const best = Object.values(block)
    .map(v => ({
      annual: toNumber(v.annualDollars),
      eDate: normalizeUnix(v.eDate),
    }))
    .filter(x => Number.isFinite(x.annual) && Number.isFinite(x.eDate) && x.eDate <= appMs)
    .sort((a, b) => b.eDate - a.eDate)[0];

  if (!best) return null;

  const pct = Math.round((gross / best.annual) * 100);
  return { incomeCheck: { calc: calcName, percent: String(pct) } };
}

const out = [];
const ami = pickEffective("AMI"); if (ami) out.push(ami);
const fpl = pickEffective("FPL"); if (fpl) out.push(fpl);

output.set("incomeChecks", out);
output.set("incomeChecksJson", JSON.stringify(out));

